// Удержание экрана включённым для киоск-режима.
//
// Основной способ — Wake Lock API (navigator.wakeLock.request('screen')).
// Если API недоступен (Firefox, старые Chromium, HTTP-контекст) или браузер
// отказал — запускаем невидимое беззвучное зацикленное видео (подход
// NoSleep.js): пока оно играет, Chromium не даёт экрану погаснуть.
//
// Отладка: откройте страницу с ?debug=1 — в правом нижнем углу появится
// индикатор состояния (wake-lock / video-fallback / none).

(function () {
  "use strict";

  var DEBUG = /[?&]debug=1(&|$)/.test(window.location.search);

  // Крошечный беззвучный webm (встроен инлайном, см. NoSleep.js)
  var VIDEO_SRC = "data:video/webm;base64,";

  var state = "none"; // "wake-lock" | "video-fallback" | "none"
  var sentinel = null;
  var inFlight = false;
  var video = null;
  var videoStarted = false;
  var badge = null;
  var started = false;
  var CHECK_INTERVAL_MS = 20000;

  function log(message) {
    console.log("[wakelock] " + message);
  }

  function warn(reason) {
    console.warn("[wakelock] " + reason);
  }

  function setState(next, detail) {
    state = next;
    if (badge) {
      badge.textContent = "screen: " + next;
      badge.setAttribute("data-state", next);
    }
    if (detail) {
      log("состояние: " + next + " — " + detail);
    }
  }

  function hasApi() {
    return !!(navigator.wakeLock && typeof navigator.wakeLock.request === "function");
  }

  function isSecure() {
    // Wake Lock доступен только в защищённом контексте (HTTPS или localhost)
    return window.isSecureContext === true;
  }

  /* ------------------------------ видео-фолбэк ------------------------------ */

  function ensureVideo() {
    if (video) return video;
    video = document.createElement("video");
    video.setAttribute("playsinline", "");
    video.setAttribute("webkit-playsinline", "");
    video.setAttribute("muted", "");
    video.setAttribute("aria-hidden", "true");
    video.muted = true;
    video.defaultMuted = true;
    video.loop = true;
    video.preload = "auto";
    video.style.cssText =
      "position:fixed;left:0;bottom:0;width:1px;height:1px;opacity:0.01;" +
      "pointer-events:none;z-index:-1;";
    video.src = VIDEO_SRC;
    document.body.appendChild(video);
    return video;
  }

  function playVideo() {
    var v = ensureVideo();
    if (document.hidden) return;
    var promise = v.play();
    if (promise && typeof promise.catch === "function") {
      promise.catch(function () {
        // Автозапуск заблокирован политикой — повторяем по первому действию
        var retry = function () {
          ensureVideo().play().catch(function () {});
        };
        ["click", "touchstart", "pointerdown", "keydown"].forEach(function (event) {
          document.addEventListener(event, retry, { once: true, passive: true });
        });
      });
    }
  }

  function pauseVideo() {
    if (video && !video.paused) {
      try {
        video.pause();
      } catch (e) {
        /* игнорируем */
      }
    }
  }

  function stopVideo() {
    if (video) pauseVideo();
  }

  function startVideoFallback(reason) {
    if (!videoStarted) {
      videoStarted = true;
      playVideo();
    } else {
      playVideo();
    }
    if (state !== "video-fallback") {
      setState("video-fallback", reason);
      log("экран удерживается видео-фолбэком");
    }
  }

  /* ------------------------------ Wake Lock ------------------------------ */

  function requestLock() {
    if (inFlight) return;                       // исключаем гонку запросов
    if (sentinel && !sentinel.released) return; // лок уже удерживается

    if (!hasApi()) {
      if (!isSecure()) {
        warn("страница открыта не по HTTPS — Wake Lock недоступен");
      } else {
        warn("API не поддерживается браузером — Wake Lock недоступен");
      }
      startVideoFallback("wake lock недоступен");
      return;
    }

    if (!isSecure()) {
      warn("страница открыта не по HTTPS — Wake Lock недоступен");
      startVideoFallback("не защищённый контекст");
      return;
    }

    inFlight = true;
    navigator.wakeLock
      .request("screen")
      .then(function (lock) {
        inFlight = false;
        sentinel = lock;
        setState("wake-lock", "экран удерживается через Wake Lock API");
        stopVideo();
        lock.addEventListener("release", function () {
          sentinel = null;
          log("лок освобождён");
          if (!document.hidden) {
            requestLock();
          }
        });
      })
      .catch(function (error) {
        inFlight = false;
        warn(
          "браузер отказал в локе" +
            (error && error.message ? ": " + error.message : "")
        );
        startVideoFallback("браузер отказал в локе");
      });
  }

  /* ------------------------------ наблюдаемость ------------------------------ */

  function createBadge() {
    if (!DEBUG || badge) return;
    badge = document.createElement("div");
    badge.id = "wakelock-badge";
    badge.textContent = "screen: none";
    badge.setAttribute("data-state", "none");
    badge.style.cssText =
      "position:fixed;right:8px;bottom:8px;z-index:2147483647;" +
      "padding:6px 10px;border-radius:8px;font:600 12px/1.2 Consolas,monospace;" +
      "background:#0f172a;color:#fff;opacity:.85;pointer-events:none;";
    document.body.appendChild(badge);
  }

  /* ------------------------------ события ------------------------------ */

  function bindEvents() {
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) {
        pauseVideo();
      } else {
        requestLock();
        if (state === "video-fallback") {
          playVideo();
        }
      }
    });

    window.addEventListener("focus", function () {
      requestLock();
    });

    document.addEventListener("fullscreenchange", function () {
      requestLock();
    });

    // Таймер-подстраховщик: лок мог быть потерян без события release
    setInterval(function () {
      if (document.hidden) return;
      if (!sentinel) {
        requestLock();
      }
    }, CHECK_INTERVAL_MS);
  }

  function start() {
    if (started) return;
    started = true;
    // Если страница встроена в iframe киоск-страницы — лок держит родитель
    if (window.self !== window.top) {
      log("страница встроена в iframe — удержание экрана выполняет родительская страница");
      return;
    }
    createBadge();
    bindEvents();
    requestLock();
  }

  // Небольшой публичный интерфейс (используется для проверки в браузере)
  window.WakeLockKeeper = {
    start: start,
    state: function () {
      return state;
    },
    force: function () {
      sentinel = null;
      requestLock();
    }
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
